import sys, importlib.util, json, struct, secrets
from pathlib import Path
from types import SimpleNamespace
from unittest.mock import patch
root=Path.cwd(); spike=root/'spikes/003-clientless-limbs'; sys.path.insert(0,str(spike))
def load(n,p):
 s=importlib.util.spec_from_file_location(n,p); m=importlib.util.module_from_spec(s); s.loader.exec_module(m); return m
r=load('probe_helpers',root/'tests/test_protocol_rereview_repairs.py')
results=[]
for stage in ['login','char']:
 l=load('temp_cleanup_probe',spike/'test_limbs.py'); clock=r.Clock(); b=l.Budget(59,clock=clock.monotonic,sleep=clock.sleep); l.fixture=r.fixture_document(); made=[]; connects=[]; sockets=[]
 class Socket(r.FakeSocket):
  def close(self): raise OSError('sanitized synthetic close failure')
  def __exit__(self,*args): self.close()
 class LiveReader:
  def __init__(self): self.live=True
  def is_alive(self): return self.live
  def join(self,**kw): self.live=False
 class MapSocket:
  def shutdown(self,*args): pass
  def close(self): pass
 actual_login=l.FixtureClient._login_server; actual_char=l.FixtureClient._char_server
 def login(bot):
  i=1 if bot.user.endswith('-1') else 2; bot.aid,bot.gid=10+i,20+i; connects.append([clock.now,i]); made.append(bot)
  if stage=='login' and len(connects)==1: return actual_login(bot)
  return '127.0.0.1',1
 def chars(bot,*args):
  if stage=='char' and len(connects)==1: return actual_char(bot,*args)
  return '127.0.0.1',1
 def maps(bot,*args): bot.sock=MapSocket(); bot.rx_thread=LiveReader()
 def create(*args,**kw):
  raw=r.client.pdb.pack(0x006a,bytes(21)) if stage=='login' else struct.pack('<I',11)+r.client.pdb.pack(0x006c,b'\x01')
  sock=Socket([raw]); sockets.append(sock); return sock
 def limb(clients,budget): l.connect_pair(clients,budget); return 'OK synthetic evidence'
 with patch.object(l.time,'monotonic',clock.monotonic),patch.object(l.FixtureClient,'_login_server',login),patch.object(l.FixtureClient,'_char_server',chars),patch.object(l.FixtureClient,'_map_server',maps),patch('socket.create_connection',create):
  l.run_limb('close-failure',limb,b,retries=1)
 assert sockets and not sockets[0].closed
 # The failed temporary transport is not represented by any tracked resource.
 assert not b.unreleased_clients
 assert made[0].sock is None and made[0].rx_thread is None and not made[0]._handshake_buffers and not made[0]._handshake_packets
 assert l.results[-1][1] is True
 results.append({'stage':stage,'retry_attempts':connects,'temporary_socket_closed':sockets[0].closed,'unreleased_clients':len(b.unreleased_clients),'limb_passed':l.results[-1][1],'result_detail':l.results[-1][3],'origin_cleanup_errors_retained':len(made[0].cleanup_errors)})
print('RESULT_JSON='+json.dumps({'reproduced':True,'cases':results,'network_calls':0}))
